```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "trace", "sql": "SELECT date_trunc('minute', time) m, SUM(CASE WHEN service_name='ts-route-plan-service' AND attr_span_kind='Client' AND attr_http_response_status_code=503 THEN 1 ELSE 0 END) rp_503, SUM(CASE WHEN service_name='ts-travel2-service' AND attr_span_kind='Server' THEN 1 ELSE 0 END) t2_server FROM abnormal_traces GROUP BY 1 ORDER BY 1", "claim": "Route-plan's 503 calls occur only in the first two abnormal minutes, when travel2 emits zero server spans; both resume after."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, metric, time, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-travel2-service%' AND metric='k8s.container.restarts' ORDER BY time LIMIT 5", "claim": "ts-travel2-service pod mqfrk shows restart counter 1 at window start; normal period had no travel2 restarts."},
        {"kind": "log", "sql": "SELECT message, COUNT(*) n FROM abnormal_logs WHERE service_name='ts-route-plan-service' AND level='SEVERE' GROUP BY 1 ORDER BY n DESC LIMIT 5", "claim": "Route-plan SEVERE logs (64) report 503 'upstream connect error... Connection refused' from a downstream callee."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.span_name client_op, s.service_name callee, COUNT(*) n, SUM(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2 ORDER BY n DESC LIMIT 15", "claim": "Route-plan calls travel2 POST/GET endpoints; its POST-to-travel2 calls fail with 503 during the travel2 outage window."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_http_response_status_code st, COUNT(*) n, AVG(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name LIKE '%minStop%' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "Route-plan minStopStations server spans return 500 about 62% of the time, surfacing in travel-plan's 500 responses."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code st, COUNT(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND span_name LIKE '%minStation%' GROUP BY 1,2,3,4", "claim": "Travel-plan minStation returns 500 and ui-dashboard's minStation requests take multi-second p95 latency, reaching the user."}]}
  ]
}
